"""Assemble all Large answers from outputs generated by the current raw run."""
from pathlib import Path
from collections import defaultdict,Counter
import argparse,csv,hashlib,json,time
import joblib,numpy as np,pandas as pd
from threadpoolctl import threadpool_limits
from train_decisions import read,save,sha,prepared,predict_voter
from decision_stages import *
from recovered.action_taxonomy import LABEL_TO_ACTION
from recovered.clip_action_routing import eligible_clips
from recovered.harn_bridge import fit_bindings,predict as harn_predict
import pair_grouping
import train_context_experts

def write_csv(path,rows,predictions):
    if set(predictions)!={r['qa_id'] for r in rows}:raise ValueError('Question coverage mismatch')
    with Path(path).open('x',encoding='utf-8',newline='') as f:
        writer=csv.writer(f,lineterminator='\r\n');writer.writerow(['qa_id','prediction'])
        for r in rows:
            value=predictions[r['qa_id']]
            if not value or not set(value)<=set(LETTERS) or len(value)!=len(set(value)):raise ValueError('Invalid answer syntax')
            if r['category']=='sequence' and set(value)!=set(LETTERS):raise ValueError('Incomplete order')
            if r['category'] not in ('sequence','multi') and len(value)!=1:raise ValueError('Single-choice answer is not singular')
            writer.writerow([r['qa_id'],value])

def compute(rows,base,temporal_data,partial_data,paths,features,occurrences,small,models,train):
    temporal={r['qa_id']:r for r in temporal_data['predictions']};partial={r['qa_id']:r for r in partial_data['predictions']}
    groups,paces,group_details=pair_grouping.predict(joblib.load(models/'recording_groups.joblib'),rows,paths,features)
    full_units={Path(unit(r)).name:unit(r) for r in rows}
    raw=defaultdict(list)
    for c in occurrences:
        if c['large_unit'] in full_units:
            raw[full_units[c['large_unit']]].append(dict(c,action=LABEL_TO_ACTION[small[c['small_key']]]))
    clips=eligible_clips(raw)
    graph_model=joblib.load(models/'compact_graph.joblib');graph=dict(graph_model.predict(pd.DataFrame(rows)).itertuples(index=False,name=None))
    voter=predict_voter(joblib.load(models/'option_voter.joblib'),prepared(rows,groups,paces))
    parent,parent_detail=parent_predictions(rows,base,partial,graph,voter,clips,groups)
    lexicon=json.loads((models/'manner_lexicon.json').read_text())
    parent_gates=json.loads((models/'parent_gates.json').read_text())
    manner={}
    if parent_gates['manner']:
        manner=train_context_experts.predict(joblib.load(models/'manner_model.joblib'),rows,paths,features,lexicon,(groups,paces,group_details))
        parent.update(manner)
    classes={Path(p).name:[small[c['small_key']] for c in values] for p,values in clips.items()}
    harn=harn_predict(rows,classes,fit_bindings(train))
    for r in harn:parent[r['qa_id']]=r['prediction']
    gates=json.loads((models/'gates.json').read_text());lexicon=json.loads((models/'manner_lexicon.json').read_text())
    final,stages=five_stages(rows,parent,clips,groups,paces,lexicon,temporal,partial,gates)
    return parent,final,{'grouping':group_details,'parent':parent_detail,'manner_parent':manner,'harn':harn,'stages':stages,'clip_recordings':len(clips),'model_gates':gates}

def run(args):
    start=time.monotonic();out=args.output;out.mkdir(parents=True,exist_ok=False)
    rows=read(args.questions)
    if any(r.get(k,'').strip() for r in rows for k in ('answer','prediction','target','label')):raise ValueError('Answer-bearing inference input')
    rows=public(rows);base={r['qa_id']:r['prediction'] for r in read(args.mil/'submission.csv')}
    # Receipts bind all intermediate outputs to the supplied raw question set.
    for path in [args.mil/'inference_manifest.json',args.clips/'execution.json',args.temporal/'execution.json']:
        report=json.loads(path.read_text())
        if report['questions_sha256']!=sha(args.questions):raise ValueError('Intermediate belongs to different questions')
    td=json.loads((args.temporal/'temporal.json').read_text());pd_=json.loads((args.temporal/'partial.json').read_text())
    f=np.load(args.temporal/'raw_features.npz',allow_pickle=False);paths=f['paths'].tolist();features=f['features']
    occurrences=json.loads((args.clips/'occurrences.json').read_text())['occurrences'];small=json.loads((args.clips/'small_predictions.json').read_text())
    train=read(args.training/'training_qa.csv')
    parent,final,evidence=compute(rows,base,td,pd_,paths,features,occurrences,small,args.models,train)
    write_csv(out/'parent.csv',rows,parent)
    for i,stage in enumerate(evidence['stages'],1):write_csv(out/f'{i}_{stage["stage"]}.csv',rows,stage.pop('predictions'))
    write_csv(out/'submission.csv',rows,final);save(out/'decision_evidence.json',evidence)
    _,reversed_result,_=compute(list(reversed(rows)),base,td,pd_,paths,features,list(reversed(occurrences)),small,args.models,train)
    if reversed_result!=final:raise ValueError('Prediction depends on input row ordering')
    report={'rows':len(rows),'parent_sha256':sha(out/'parent.csv'),'final_sha256':sha(out/'submission.csv'),'raw_model_runs':{'mil':str(args.mil),'temporal':str(args.temporal),'clips':str(args.clips)},'source_sha256':sha(__file__),'models_validation_sha256':sha(args.models/'validation.json'),'historical_prediction_inputs':False,'selected_submission_read':False,'row_order_invariance':True,'seconds':time.monotonic()-start,'stages':[{'stage':s['stage'],'enabled':s['enabled'],'changes':len(s['proposed_changes']) if s['enabled'] else 0,'proposals':len(s['proposed_changes'])} for s in evidence['stages']],'raw_groups':len(evidence['grouping']),'harn_bridge_answers':len(evidence['harn'])}
    save(out/'execution.json',report);print(json.dumps(report,indent=2),flush=True)
if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__)
    for key in ['questions','mil','temporal','clips','models','training','output']:p.add_argument('--'+key,type=Path,required=True)
    with threadpool_limits(limits=2):run(p.parse_args())
